#!/usr/bin/env python3
"""Chromium interaction/routing witness, not the production UI or SQLite WASM.
The endpoint returns tiny mock index responses, not search results from SQLite.
Run: python routing.py REPORT.json [chromium executable]
"""
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
import json,sys,threading,time
from pathlib import Path
from urllib.parse import urlparse,parse_qs
from playwright.sync_api import sync_playwright
HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Work versions</title><style>[hidden]{display:none!important}body{font:1rem system-ui;max-width:50rem;margin:auto;padding:1rem}form{display:grid;gap:.7rem}input,button,select{font:inherit;min-width:0;max-width:100%}.query{display:flex;gap:.4rem}.query input{flex:1}#notice{margin:0;color:#555}</style><h1>Versions</h1><form role="search" hidden id="search"><label for="scope">Search scope</label><select id="scope" name="scope"><option value="versions">Versions</option><option value="history">Complete history (passages)</option></select><p id="notice" hidden>Search passages across all published versions. This may require larger downloads and take longer.</p><label for="q" id="qlabel">Search versions and commit messages</label><div class="query"><input id="q" type="search" required><button type="submit">Search</button></div><button id="cancel" type="button" hidden>Cancel</button></form><p role="status" id="status" aria-live="polite"></p><ol id="static"><li><a href="/edition/v5">v5</a></li><li><a href="/edition/v1">v1</a></li></ol><ol id="results"></ol><script>
const form=document.querySelector('#search'),scope=document.querySelector('#scope'),q=document.querySelector('#q'),notice=document.querySelector('#notice'),label=document.querySelector('#qlabel'),status=document.querySelector('#status'),results=document.querySelector('#results'),staticList=document.querySelector('#static'),cancel=document.querySelector('#cancel');
let generation=0, active=null;
function clear(){++generation;active?.abort();active=null;cancel.hidden=true;results.replaceChildren();staticList.hidden=false;status.textContent='';}
function controls(){notice.hidden=scope.value!=='history';label.textContent=scope.value==='history'?'Search passages across all versions':'Search versions and commit messages';}
function write(qvalue){const u=new URL(location.href);u.search='';if(scope.value==='history')u.searchParams.set('scope','history');if(qvalue)u.searchParams.set('q',qvalue);history.pushState(null,'',u);}
async function submit(){clear();let term=q.value.trim();if(!term)return;let seq=generation,kind=scope.value;active=new AbortController();cancel.hidden=false;status.textContent='Searching…';try{const r=await fetch('/mock-index/'+kind+'?q='+encodeURIComponent(term),{signal:active.signal,cache:'no-store'});if(!r.ok)throw Error('request failed');const data=await r.json();if(term==='slow')await new Promise(resolve=>setTimeout(resolve,600));if(seq!==generation)return;staticList.hidden=true;for(const item of data.rows){let li=document.createElement('li'),a=document.createElement('a');a.textContent=item.text;a.href=item.href;li.append(a);results.append(li);}status.textContent=data.rows.length+' results';}catch(e){if(seq===generation)status.textContent='Search failed. Retry with Search.';}finally{if(seq===generation){active=null;cancel.hidden=true;}}}
form.addEventListener('submit',e=>{e.preventDefault();write(q.value.trim());submit();});scope.addEventListener('change',()=>{clear();controls();write('');});cancel.addEventListener('click',()=>{clear();status.textContent='Search cancelled.';});function restore(){clear();let u=new URL(location.href);scope.value=u.searchParams.get('scope')==='history'?'history':'versions';q.value=u.searchParams.get('q')||'';controls();if(q.value.trim())submit();}window.addEventListener('popstate',restore);form.hidden=false;restore();</script></html>'''
# Offline test double: browser network access is blocked in this environment.
# Inject mock fetch and URL history; test DOM/state only, not network/deep-link delivery.
MOCK="""<script>window.testUrl='https://fixture.invalid/';window.routeLog=[];let failed=false;window.fetch=async function(url,options){let u=new URL(url,window.testUrl),kind=u.pathname.split('/').pop(),term=u.searchParams.get('q');routeLog.push([kind,term]);if(term==='retry'&&!failed){failed=true;return new Response('',{status:503});}return new Response(JSON.stringify({rows:[{text:kind==='history'?'Passage in v1':'v5',href:kind==='history'?'/edition/v1#anchor':'/edition/v5'}]}),{status:200});};</script>"""
HTML=HTML.replace('<script>',''+MOCK+'<script>',1).replace('new URL(location.href)','new URL(window.testUrl)').replace("history.pushState(null,'',u)","window.testUrl=u.href")
checks=[]
with sync_playwright() as p:
    b=p.chromium.launch(executable_path=sys.argv[2] if len(sys.argv)>2 else '/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':375,'height':667});page.set_content(HTML)
    def requests():return [tuple(row) for row in page.evaluate("routeLog")]
    def check(name,fn):assert fn(),name;checks.append(name)
    check('one search component, default Versions',lambda:page.locator('form[role=search]').count()==1 and page.locator('#scope').input_value()=='versions')
    check('static editions, no index fetch on open',lambda:page.locator('#static').is_visible() and requests()==[])
    page.locator('#q').fill('name');page.locator('#q').press('Enter');page.get_by_role('status').get_by_text('1 results').wait_for();check('ordinary version request only',lambda:requests()==[('versions','name')] and page.locator('#results a').get_attribute('href')=='/edition/v5')
    page.locator('#scope').select_option('history');check('notice visible, selection fetches nothing',lambda:page.locator('#notice').is_visible() and len(requests())==1 and page.locator('#static').is_visible())
    check('mobile width and accessible label',lambda:page.evaluate('document.documentElement.scrollWidth===innerWidth') and page.get_by_label('Search scope').count()==1)
    page.locator('#q').fill('term');page.get_by_role('button',name='Search',exact=True).click();page.get_by_role('status').get_by_text('1 results').wait_for();check('explicit history query and exact passage route',lambda:requests()[-1]==('history','term') and page.locator('#results a').get_attribute('href')=='/edition/v1#anchor')
    page.locator('#q').fill('slow');page.locator('#q').press('Enter');page.wait_for_timeout(100);page.locator('#scope').select_option('versions');page.locator('#q').fill('new');page.locator('#q').press('Enter');page.get_by_role('status').get_by_text('1 results').wait_for();page.wait_for_timeout(700);check('scope switch cancels stale history response',lambda:page.locator('#results a').get_attribute('href')=='/edition/v5')
    page.locator('#scope').select_option('history');page.locator('#q').fill('slow');page.locator('#q').press('Enter');page.get_by_role('button',name='Cancel').click();page.wait_for_timeout(700);check('explicit cancellation',lambda:page.get_by_role('status').inner_text()=='Search cancelled.' and page.locator('#results li').count()==0)
    page.locator('#q').fill('retry');page.locator('#q').press('Enter');page.get_by_role('status').get_by_text('Search failed. Retry with Search.').wait_for();page.locator('#q').press('Enter');page.get_by_role('status').get_by_text('1 results').wait_for();check('failure is not an empty result; retry works',lambda:requests()[-2:]==[('history','retry'),('history','retry')])
    before=len(requests());page.evaluate("window.testUrl='https://fixture.invalid/?scope=history';restore()");page.wait_for_timeout(100);check('history mode deep link without query is not opt-in execution',lambda:len(requests())==before and page.locator('#notice').is_visible())
    page.evaluate("window.testUrl='https://fixture.invalid/?scope=history&q=deep';restore()");page.get_by_role('status').get_by_text('1 results').wait_for();check('explicit history-query deep link',lambda:requests()[-1]==('history','deep'))
    nojs=b.new_context(java_script_enabled=False).new_page();before=len(requests());nojs.set_content(HTML);check('static list without JS and no index fetch',lambda:nojs.locator('#static a').count()==2 and len(requests())==before and not nojs.locator('#search').is_visible())
    version=b.version;request_log=requests();b.close()
Path(sys.argv[1]).write_text(json.dumps({'result':'passed','browser':version,'checks':checks,'requests':request_log,'limitation':'Offline DOM harness with in-page fetch and URL-history test doubles; localhost and fulfilled virtual HTTP navigation blocked by administrator. No network transfer, actual browser URL navigation, production UI, SQLite WASM or end-to-end search. Delayed mock decode exercises stale-response guard.'},indent=2)+'\n');print('PASS',len(checks))
